function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Vector2D' || args[0].length !== 1) return 'Start with Vector2D and the array vec.';
  const vec = args[0][0];
  if (vec.length > 200) return 'vec has at most 200 rows.';
  if (vec.some(row => row.length > 500)) return 'Each row has at most 500 numbers.';
  if (vec.some(row => row.some(v => v < -500 || v > 500))) return 'Each number is between -500 and 500.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls to next and hasNext.';
  let left = vec.reduce((sum, row) => sum + row.length, 0);
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'next' && operations[i] !== 'hasNext') return 'Only next and hasNext can follow the constructor.';
    if (args[i].length !== 0) return `${operations[i]} takes no arguments.`;
    if (operations[i] === 'next' && left-- === 0) return 'next is only called while a number is left.';
  }
  return null;
}

