class Vector2D {
  constructor(vec) {
    this.vec = vec;
    this.row = 0;
    this.col = 0;
  }

  skipEmpty() {
    while (this.row < this.vec.length && this.col === this.vec[this.row].length) {
      this.row++;
      this.col = 0;
    }
  }

  next() {
    this.skipEmpty();
    const value = this.vec[this.row][this.col];
    this.col++;
    return value;
  }

  hasNext() {
    this.skipEmpty();
    return this.row < this.vec.length;
  }
}

