class Vector2D {
  constructor(vec) {
    // Copy every number into one flat list up front.
    this.items = [];
    for (const line of vec) for (const value of line) this.items.push(value);
    this.index = 0;
  }
  next() {
    return this.items[this.index++];
  }
  hasNext() {
    return this.index < this.items.length;
  }
}

