function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const rows = large ? 200 : pick(6);
  const span = large || rand() < 0.4 ? 500 : 3;
  const emptyRate = rand() * 0.6;
  const vec = [];
  let total = 0;
  for (let r = 0; r < rows; r++) {
    const length = rand() < emptyRate ? 0 : 1 + pick(large ? 4 : 3);
    vec.push(Array.from({ length }, () => pick(2 * span + 1) - span));
    total += length;
  }
  const operations = ['Vector2D'];
  const args = [[vec]];
  const calls = large ? 499 : 1 + pick(12);
  const askRate = rand() * 0.6;
  let left = total;
  for (let i = 0; i < calls; i++) {
    // next is only called while a number is left, as the problem guarantees.
    if (left > 0 && rand() >= askRate) {
      operations.push('next');
      left--;
    } else {
      operations.push('hasNext');
    }
    args.push([]);
  }
  return [operations, args];
}
